// Package web serves the production frontend from the executable, without
// extracting files or reading a directory on the host.
package web

import (
	"embed"
	"io/fs"
	"net/http"
	"path"
	"strings"
)

// Generated by make frontend before compiling Go. Never embed configuration,
// snapshots, the checkout, or the separate public demo build.
//
//go:embed dist
var content embed.FS

func Handler() (http.Handler, error) {
	files, err := fs.Sub(content, "dist")
	if err != nil {
		return nil, err
	}
	fileServer := http.FileServer(http.FS(files))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}
		name := strings.TrimPrefix(path.Clean("/"+r.URL.Path), "/")
		if name == "" {
			name = "index.html"
		}
		entry, err := fs.Stat(files, name)
		if err != nil || !entry.Mode().IsRegular() {
			// Do not expose directory listings or turn missing assets into HTML.
			http.NotFound(w, r)
			return
		}
		if strings.HasPrefix(name, "assets/") {
			w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		} else {
			w.Header().Set("Cache-Control", "no-cache")
		}
		fileServer.ServeHTTP(w, r)
	}), nil
}
